// Ponto unico de parsing da saida do LLM.
// Se o agente devolver JSON sujo (crases, markdown, texto antes/depois),
// a limpeza acontece aqui e nao contamina o resto do fluxo.
const bruto = $input.first().json.output ?? '';
const limpo = String(bruto).replace(/```json|```/g, '').trim();
const inicio = limpo.indexOf('{');
const fim = limpo.lastIndexOf('}');

let dados;
try {
  dados = JSON.parse(limpo.slice(inicio, fim + 1));
} catch (e) {
  dados = {
    empresa: null, contato: null, cargo: null, num_linhas: null,
    operadora: null, necessidade: null, plano_sugerido: null,
    score: 0, temperatura: 'frio',
    dossie: 'Falha ao estruturar a qualificacao. Saida bruta: ' + limpo.slice(0, 400)
  };
}

const n = parseInt(dados.num_linhas, 10);
dados.num_linhas = Number.isFinite(n) ? n : null;
dados.score = parseInt(dados.score, 10) || 0;

return [{ json: dados }];

